const KEY='job-search-dashboard-v1';
let channelCoverage=null;let employerProfiles=window.EMPLOYER_PROFILES_BUILTIN||null;
const $=s=>document.querySelector(s), esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const today=()=>new Date().toLocaleDateString('en-CA');
function monday(){let d=new Date();d.setDate(d.getDate()-(d.getDay()+6)%7);return d.toLocaleDateString('en-CA')}
var CAL_CLOSED=['暂不继续','已结束','已入职'],calMonth=new Date().toLocaleDateString('en-CA').slice(0,7);
let state=structuredClone(SEED),view='overview',week=monday(),query='',market='全部',showArchived=false,editing=null;
function valid(s){
 if(!s||s.version!==1||typeof s.review!=='string')return false;
 if(s.reviews&&(!s.reviews||Array.isArray(s.reviews)||typeof s.reviews!=='object'||Object.values(s.reviews).some(v=>typeof v!=='string')))return false;
 return ['tasks','jobs','contacts'].every(k=>Array.isArray(s[k])&&new Set(s[k].map(x=>x?.id)).size===s[k].length&&s[k].every(x=>x&&typeof x.id==='string'&&/^[a-zA-Z0-9_-]+$/.test(x.id)&&typeof x.title==='string'&&['detail','market','kind','status','priority','week','due','note','url','group','line','nextAction','focus','comment','deadline','deadlineBasis','starredAt','jobIds'].every(f=>x[f]===undefined||typeof x[f]==='string')&&['archived','today','starred'].every(f=>x[f]===undefined||typeof x[f]==='boolean')));
}
let storageError='';try{const raw=localStorage.getItem(KEY);if(raw){const parsed=JSON.parse(raw);if(!valid(parsed))throw Error('invalid');state=parsed}}catch(e){storageError='旧数据读取失败，未覆盖原记录。请先导出或导入有效备份。'}
function save(){if(storageError){$('#saveStatus').textContent=storageError;return false}try{localStorage.setItem(KEY,JSON.stringify(state));$('#saveStatus').textContent='已保存 · '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'})+(fs.ready?' · 文件同步中':fs.handle?' · 文件夹待授权':'');scheduleFileSave();return true}catch(e){$('#saveStatus').textContent='保存失败，请立即导出备份';return false}}
// —— 机会清单按阶段分栏（2026-09-30 Claude）——
const APPLIED=['已投递','已联系','面试中','Offer','已入职'];
const STAGES=[
 {key:'active',title:'正在推进',sub:'待评估 · 准备申请',match:s=>['待评估','准备申请'].includes(s),open:true,empty:'没有正在推进的岗位。在上方待浏览里点"处理"或"直接准备申请"。'},
 {key:'applied',title:'已投递',sub:'已投递 · 已联系 · 面试中 · Offer · 已入职',match:s=>APPLIED.includes(s),open:true,empty:'还没有投递记录。投完后把岗位状态改成"已投递"。',dated:true},
 {key:'later',title:'稍后',sub:'暂缓，之后再看',match:s=>s==='稍后',open:false,empty:'没有暂缓的岗位。'},
 {key:'closed',title:'不再跟进',sub:'暂不继续 · 已结束',match:s=>['暂不继续','已结束'].includes(s),open:false,empty:'没有。'}];
const stageOpen={};
function appSummary(x){return x.summary||((window.APPLICATION_SUMMARIES||{})[x.id]||{}).page||''}
function jobRow(x,dated){return `<tr><td>${typeof orgBadge==='function'?orgBadge(x):''}<strong>${hl(x.title)}</strong><div class="meta">${hl(x.detail)}${x.url?` · <a href="${esc(x.url)}" target="_blank" rel="noopener">官网 ↗</a>`:''}${appSummary(x)?` · <a href="${esc(appSummary(x))}" target="_blank" rel="noopener"><b>投递摘要 ↗</b></a>`:''}</div></td><td>${esc(x.market)}<div class="meta">${esc(x.kind)}</div></td><td>${scoreCell(x)}</td><td>${badge(x.status)}${x.priority&&!dated?badge(x.priority+'优先'):''}</td>${dated?`<td>${x.appliedAt?esc(x.appliedAt):x.decidedAt?esc(x.decidedAt)+'<div class="meta">状态变更日</div>':'<span class="meta">未记录</span>'}</td>`:''}<td>${due(x.due)||'未设定'}${x.deadline&&!APPLIED.includes(x.status)?`<div>${dlBadge(x)}</div>`:''}</td><td class="nowrap">${starBtn(x)} <button class="small" data-edit="jobs:${esc(x.id)}">查看 / 编辑</button></td></tr>`}
function jobSections(arr){
 const order={'准备申请':0,'待评估':1,'Offer':0,'面试中':1,'已联系':2,'已投递':3,'已入职':4};
 return STAGES.map(st=>{let rows=arr.filter(x=>st.match(x.status));
  if(st.key==='other')return '';
  rows.sort(st.dated?(p,q)=>String(q.appliedAt||q.decidedAt||'').localeCompare(String(p.appliedAt||p.decidedAt||''))||(order[p.status]??9)-(order[q.status]??9):(p,q)=>(order[p.status]??9)-(order[q.status]??9)||(q.scout?.total||0)-(p.scout?.total||0));
  if(query&&!rows.length)return '';const isOpen=query?true:(stageOpen[st.key]??st.open);
  return `<details class="panel stage-panel stage-${st.key}" data-stage="${st.key}" ${isOpen?'open':''} style="margin-top:18px"><summary><b>${st.title} · ${rows.length}</b> <span class="meta">${st.sub}</span></summary>${rows.length?`<div class="table-wrap"><table><thead><tr><th>公司 / 岗位</th><th>市场 / 类型</th><th>分数</th><th>状态</th>${st.dated?'<th>投递日期</th>':''}<th>下次跟进 / 截止</th><th>操作</th></tr></thead><tbody>${rows.map(x=>jobRow(x,st.dated)).join('')}</tbody></table></div>`:empty(st.empty)}</details>`}).join('')+unmatched(arr)}
function unmatched(arr){const rest=arr.filter(x=>!STAGES.some(st=>st.match(x.status)));return rest.length?`<div class="panel" style="margin-top:18px"><h2>其他状态 · ${rest.length}</h2><div class="table-wrap"><table><tbody>${rest.map(x=>jobRow(x,false)).join('')}</tbody></table></div></div>`:''}
document.addEventListener('toggle',e=>{const d=e.target;if(d&&d.dataset&&d.dataset.stage&&!query)stageOpen[d.dataset.stage]=d.open},true);

function badge(s){return '<span class="badge">'+esc(s)+'</span>'}
function due(s){return s?'<span class="badge '+(s<today()?'late':'')+'">'+esc(s)+(s<today()?' · 已到期':'')+'</span>':''}
const titles={overview:'把今天往前推进一点。',tasks:'每周两条线，持续往前。',jobs:'从发现，到下一次对话。',contacts:'让联系有后续。',review:'看见进展，调整下一周。',files:'资料与数据，留在自己手里。'};
function taskRow(t){const d=t.status==='完成';return `<div class="row task-row ${d?'is-done':''}"><input aria-label="完成 ${esc(t.title)}" type="checkbox" data-check="${esc(t.id)}" ${d?'checked':''}><div class="grow"><div class="task-title ${d?'done':''}" data-title="${esc(t.id)}" tabindex="0" title="点击直接修改标题">${esc(t.title)}</div><div class="meta">${badge(t.status)}${badge(t.priority+'优先')}${due(t.due)}${t.line?badge(t.line):''}${t.focus?badge(t.focus):''}${rollBadges(t)}${taskJobChips(t)}${t.nextAction?'<div class="note">下一步：'+esc(t.nextAction)+'</div>':''}${t.note?'<div class="note">'+esc(t.note)+'</div>':''}</div></div><button class="small" data-pin="${esc(t.id)}" aria-label="${t.today?'移出':'加入'}今日">${t.today?'★':'☆'}</button><button class="small" data-edit="tasks:${esc(t.id)}">详情</button></div>`}
const justToggled=new Set();let lastPlace='';
const settled=t=>t.status==='完成'&&!justToggled.has(t.id);
const undoneFirst=a=>[...a.filter(t=>!settled(t)),...a.filter(settled)];
const doneToday=t=>t.status==='完成'&&t.doneAt===today();
const inWeek=t=>t.week===week||(Array.isArray(t.rolledWeeks)&&t.rolledWeeks.includes(week));
const md=d=>String(d||'').slice(5).replace('-','/');
function rollBadges(t){let h='';const rw=Array.isArray(t.rolledWeeks)?t.rolledWeeks:[];if(rw.includes(week)&&t.week!==week)h+=`<span class="roll-badge">↪ 未完成，已顺延到 ${esc(md(t.week))} 这周</span>`;else if(rw.length&&t.status!=='完成')h+=`<span class="roll-badge">↪ 自 ${esc(md(rw[0]))} 那周顺延${rw.length>1?' · 第 '+rw.length+' 次':''}</span>`;if(t.today&&t.todayFrom&&t.status!=='完成')h+=`<span class="roll-badge day">↻ 自 ${esc(md(t.todayFrom))} 起未完成，顺延到今天</span>`;return h}
// —— 未完成任务自动顺延（2026-09-28 Claude）：上周及更早未完成、未归档的任务移到本周；今日聚焦里未完成的逐日顺延 ——
function rollOver(){if(storageError||!Array.isArray(state.tasks))return 0;const wk=monday(),td=today();let n=0;for(const t of state.tasks){if(!t||t.archived)continue;if(t.today&&!t.todayAt){t.todayAt=td;n++}if(t.status==='完成')continue;if(t.week&&t.week<wk){t.rolledWeeks=Array.isArray(t.rolledWeeks)?t.rolledWeeks:[];if(!t.rolledWeeks.includes(t.week))t.rolledWeeks.push(t.week);t.week=wk;n++}if(t.today&&t.todayAt<td){t.todayFrom=t.todayFrom||t.todayAt;t.todayAt=td;n++}}return n}
function rollOverNow(){const wk=monday();if(rollOver()){if(week<wk&&view!=='review')week=wk;save();render()}else if(week<wk&&lastRollWeek<wk){week=wk;render()}lastRollWeek=wk}
let lastRollWeek=monday();
