 let ts=state.tasks.filter(t=>!!t.archived===(view==='tasks'&&showArchived)&&inWeek(t)),done=ts.filter(t=>t.status==='完成').length,js=state.jobs.filter(j=>!j.archived),cs=state.contacts.filter(c=>!c.archived);
 const overdue=[...js,...cs].filter(x=>x.due&&x.due<=today()&&!['已结束','暂不继续','已完成','已入职'].includes(x.status));
 $('#stats').innerHTML=[[done+'/'+ts.length,'所选周 · 已完成任务'],[js.filter(j=>j.status==='待浏览').length+' / '+js.length,'待浏览 / 全部机会'],[js.filter(j=>APPLIED.includes(j.status)).length,'已投递 · 含面试及以后'],[js.filter(j=>j.status==='面试中').length,'面试中的机会'],[soonDeadlines().length,'两周内投递截止'],[overdue.length,'我定的跟进日已到']].map(([n,l],i)=>{const [v,j]=[['tasks',''],['jobs','inbox'],['jobs','applied'],['jobs','applied'],['calendar','soon'],['overview','follow']][i];return `<button type="button" class="stat" data-view="${v}" data-jump="${j}" title="点击查看对应列表"><strong>${n}</strong><span>${l} ›</span></button>`}).join('');
 const fkey=view+'|'+market+'|'+showArchived+'|'+week,fEl=$('#filters');if(!(['jobs','contacts'].includes(view)&&fEl.dataset.key===fkey&&$('#search'))){fEl.dataset.key=fkey;fEl.innerHTML=['overview','tasks','review'].includes(view)?`<label>周一起始日期 <input type="date" id="week" value="${week}"></label><span class="meta">每日按依赖、紧急度、机会价值和精力选择；☆ 加入今日</span>${view==='tasks'?`<label><input id="archived" type="checkbox" ${showArchived?'checked':''}>查看归档</label>`:''}`:['jobs','contacts'].includes(view)?`<div class="search-box"><span class="search-ico" aria-hidden="true">⌕</span><input id="search" type="search" autocomplete="off" aria-label="搜索" placeholder="${view==='jobs'?'搜索公司、岗位、地点、备注… 多个词用空格隔开（按 / 键快速搜索）':'搜索姓名、组织或备注'}" value="${esc(query)}"><button type="button" class="small" id="clearSearch" ${query?'':'hidden'}>清空</button></div><span id="searchCount" class="meta"></span><select id="market" aria-label="市场筛选">${['全部','美国','中国','其他'].map(v=>`<option ${market===v?'selected':''}>${v}</option>`).join('')}</select><label><input id="archived" type="checkbox" ${showArchived?'checked':''}>查看归档</label>`:''}
 if(['jobs','contacts'].includes(view)){const c=$('#clearSearch');if(c)c.hidden=!query}
 if(view==='overview'){$('#content').innerHTML=`<div class="grid"><div class="panel"><h2>今日聚焦</h2>${quickAdd('today',{today:true})}${undoneFirst(state.tasks.filter(t=>!t.archived&&t.today&&(t.status!=='完成'||doneToday(t)))).map(taskRow).join('')||empty('还没有选定今日任务。直接在上面输入，或在周清单中点 ☆。')}</div><div><div class="panel accent"><h2>本周进度</h2><div class="progress"><div style="width:${ts.length?100*done/ts.length:0}%"></div></div><p class="meta">本周清单完成 ${done} / ${ts.length} · 不是申请数量考核</p></div>${starPanel(true)}<div class="panel" id="soonPanel" style="margin-top:20px"><h2>两周内投递截止</h2><p class="meta">还没投、且投递截止日期在 14 天内（含已过期）的岗位。<button class="small linkish" data-view="calendar">打开日历 ›</button></p>${soonDeadlines().map(calRow).join('')||empty('两周内没有已知的投递截止。没写截止日期的岗位列在「日历与截止」页底部。')}</div><div class="panel" id="followPanel" style="margin-top:20px"><h2>需要跟进</h2><p class="meta">"下次跟进"日期是今天或已过、且没有结束的岗位和联系人。</p>${overdue.map(x=>`<div class="row"><div class="grow">${esc(x.title)}${x.detail?`<div class="meta">${esc(x.detail)}</div>`:''}<div>${due(x.due)}${x.status?badge(x.status):''}</div></div><button class="small" data-edit="${js.includes(x)?'jobs':'contacts'}:${esc(x.id)}">查看</button></div>`).join('')||empty('暂无已录入的到期跟进。')}</div></div></div>`}
 if(view==='overview'){
 const lines=['对外材料','机会发现','管线执行','面试准备'];
 $('#content').innerHTML+='<div class="grid operating-lines" style="margin-top:22px">'+lines.map(line=>{
 const records=state.tasks.filter(t=>!t.archived&&t.line===line&&inWeek(t));
 const focus=records.filter(t=>t.priority==='高'&&t.status!=='完成');
 const shown=[...(focus.length?focus:records.filter(t=>t.status!=='完成')).slice(0,3),...records.filter(doneToday)];
 return `<div class="panel"><h2>${line}</h2><div class="meta">${records.filter(t=>t.status==='进行中').length} 项进行中 · ${records.filter(t=>t.status==='阻塞').length} 项阻塞</div>${quickAdd('line-'+line,{line,group:line==='面试准备'?'学习准备':'求职操作'})}${shown.map(taskRow).join('')||empty('暂无未完成任务；按真实进度维护。')}</div>`;
 }).join('')+'</div>';
 }
 if(view==='tasks'){$('#content').innerHTML='<div class="grid">'+['求职操作','学习准备'].map(g=>`<div class="panel"><h2>${g}</h2>${showArchived?'':quickAdd('group-'+g,{group:g,line:g==='学习准备'?'面试准备':''})}${undoneFirst(ts.filter(t=>t.group===g)).map(taskRow).join('')||empty('本周还没有任务。直接在上面输入即可添加。')}</div>`).join('')+'</div>'}
 if(['jobs','contacts'].includes(view)){const arr=state[view].filter(x=>!!x.archived===showArchived&&(market==='全部'||x.market===market)&&(view!=='jobs'||x.status!=='待浏览'||showArchived)&&matchQuery(x));if(view==='jobs')arr.sort((p,q)=>(q.scout?.total||0)-(p.scout?.total||0));
 const inboxHtml=view==='jobs'&&!showArchived?searchSummary()+starPanel(false)+inboxPanel()+withdrawnPanel()+(query?'':coveragePanel()):'';const sc=$('#searchCount');if(sc)sc.textContent=query?'找到 '+(view==='jobs'&&!showArchived?lastJobHits:arr.length)+(view==='jobs'?' 个岗位':' 条'):'';
 if(view==='jobs'&&!showArchived){$('#content').innerHTML=inboxHtml+jobSections(arr);return}
 $('#content').innerHTML=inboxHtml+`<div class="panel"><h2>${view==='jobs'?'机会清单':'联系记录'}</h2><p class="meta">${view==='jobs'?'待浏览的岗位在上方处理；这里是你已经看过、正在推进或暂放的记录。':'尚未自动导入旧 Excel / CSV；这里的数字仅统计你在工作台录入的记录。'}</p>${arr.length?`<div class="table-wrap"><table><thead><tr><th>${view==='jobs'?'公司 / 岗位':'姓名 / 所属组织'}</th><th>市场 / 类型</th>${view==='jobs'?'<th>分数</th>':''}<th>状态</th><th>下次跟进</th><th>操作</th></tr></thead><tbody>${arr.map(x=>`<tr><td>${view==='jobs'?orgBadge(x):''}<strong>${esc(x.title)}</strong><div class="meta">${esc(x.detail)}${x.url?` · <a href="${esc(x.url)}" target="_blank" rel="noopener">官网 ↗</a>`:''}${appSummary(x)?` · <a href="${esc(appSummary(x))}" target="_blank" rel="noopener"><b>投递摘要 ↗</b></a>`:''}</div></td><td>${esc(x.market)}<div class="meta">${esc(x.kind)}</div></td>${view==='jobs'?`<td>${scoreCell(x)}</td>`:''}<td>${badge(x.status)}${x.priority?badge(x.priority+'优先'):''}</td><td>${due(x.due)||'未设定'}</td><td><button class="small" data-edit="${view}:${esc(x.id)}">查看 / 编辑</button></td></tr>`).join('')}</tbody></table></div>`:empty(view==='jobs'?'还没有已处理的岗位。':'还没有记录。新增一条真实机会或联系人，从下一步行动开始。')}</div>`}
 if(view==='calendar'){$('#content').innerHTML=calendarView();return}
