function edit(kind,id){const item=state[kind].find(x=>x.id===id)||{week,priority:'中'};editing={kind,id};$('#editTitle').textContent=id?'编辑记录':'新增记录';$('#archive').hidden=!id;$('#archive').textContent=item.archived?'恢复此记录':'归档此记录';const linkBlock=kind==='tasks'?taskJobsBlock(item):kind==='jobs'&&id?jobTasksBlock(item):'';const scoutBlock=kind==='jobs'&&item.scout?`<div class="wide scout-block">${scoutDetail(item)}</div>`:(kind==='jobs'&&employerInfo(item)?`<div class="wide scout-block">${orgDetail(item)}</div>`:'');$('#fields').innerHTML=(kind==='tasks'?linkBlock+scoutBlock:scoutBlock+linkBlock)+spec[kind].map(([k,l,type])=>`<label class="${['title','note','url','jobIds'].includes(k)?'wide':''}">${l}${type==='jobpick'?jobPicker(item):Array.isArray(type)?`<select name="${k}">${type.map(v=>`<option ${item[k]===v?'selected':''}>${esc(v)}</option>`).join('')}</select>`:type==='textarea'?`<textarea name="${k}">${esc(item[k])}</textarea>`:`<input name="${k}" type="${type}" value="${esc(item[k])}" ${k==='title'?'required maxlength="250"':''}>`}</label>`).join('');$('#editor').showModal()}
