document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b)return;if(b.dataset.view){view=b.dataset.view;query='';$('#filters').dataset.key='';showArchived=false;if(b.dataset.jump==='applied')stageOpen.applied=true;render();if(b.dataset.jump)jumpTo(b.dataset.jump)}if(b.dataset.star){const j=state.jobs.find(x=>x.id===b.dataset.star);if(j){j.starred=!j.starred;j.starredAt=j.starred?today():'';save();render()}return}if(b.dataset.calMonth){calMonth=shiftMonth(calMonth,+b.dataset.calMonth);render()}if(b.dataset.edit){const [kind,id]=b.dataset.edit.split(':');edit(kind,id)}if(b.dataset.pin){const t=state.tasks.find(x=>x.id===b.dataset.pin);t.today=!t.today;t.todayAt=t.today?today():'';if(!t.today)t.todayFrom='';save();render()}if(b.id==='clearSearch'){query='';const i=$('#search');if(i){i.value='';i.focus()}render();return}if(b.id==='dismissConflicts'){state.handoverConflicts=[];save();render()}if(b.dataset.act){const j=state.jobs.find(x=>x.id===b.dataset.id);if(j){const box=document.querySelector(`textarea[data-comment="${CSS.escape(j.id)}"]`);if(box)j.comment=box.value.trim();const act=b.dataset.act;if(act==='process')j.status='待评估';if(act==='later'){j.status='稍后';j.priority='低'}if(act==='ignore')j.status='暂不继续';if(act==='apply')j.status='准备申请';j.decidedAt=today();save();render()}}if(b.id==='fsConnect')fs.connect();if(b.id==='fsGrant')fs.grant();if(b.id==='fsImport')fs.importInbox(true);if(b.id==='fsWrite')fs.writeState(true);if(b.id==='fsBannerGrant')fs.grant();if(b.id==='add')edit(['jobs','contacts'].includes(view)?view:'tasks');if(b.id==='close')$('#editor').close();if(['export','backup'].includes(b.id))exportData();if(b.id==='import')$('#importFile').click();if(b.id==='archive'){const t=state[editing.kind].find(x=>x.id===editing.id);t.archived=!t.archived;save();$('#editor').close();render()}if(b.id==='saveReview'){state.reviews=state.reviews||{};state.reviews[week]=$('#reviewText').value;save()}});
document.addEventListener('change',e=>{if(e.target.dataset.check){const t=state.tasks.find(x=>x.id===e.target.dataset.check);justToggled.add(t.id);t.status=e.target.checked?'完成':'待办';t.doneAt=e.target.checked?today():'';save();render()}if(e.target.id==='week'){week=e.target.value||monday();render()}if(e.target.id==='market'){market=e.target.value;render()}if(e.target.id==='archived'){showArchived=e.target.checked;render()}});
let commentTimer;document.addEventListener('input',e=>{if(e.target.dataset?.comment){const j=state.jobs.find(x=>x.id===e.target.dataset.comment);if(j){j.comment=e.target.value;e.target.style.height='auto';e.target.style.height=e.target.scrollHeight+'px';clearTimeout(commentTimer);commentTimer=setTimeout(()=>save(),600)}return}if(e.target.id==='search'){if(e.isComposing)return;query=e.target.value.trim();render()}});
$('#editForm').addEventListener('submit',e=>{e.preventDefault();const data=Object.fromEntries(new FormData(e.target));data.title=data.title.trim();if(!data.title)return;const arr=state[editing.kind],item=arr.find(x=>x.id===editing.id);if(editing.kind==='jobs'){if(item&&data.status&&data.status!==item.status)data.decidedAt=today();if(APPLIED.includes(data.status)&&!data.appliedAt&&!(item&&item.appliedAt))data.appliedAt=today();}if(item)Object.assign(item,data);else arr.push({id:crypto.randomUUID(),archived:false,today:false,...data});save();$('#editor').close();render()});
