function mergeHandover(input){
 const out=structuredClone(input);if(out.baseline===SEED.baseline)return out;
 const previous={tasks:[]}; // TODO: seed-update history was personal and has been removed
 const conflicts=[...(out.handoverConflicts||[])];
 for(const fresh of SEED.tasks){
  const original=previous.tasks.find(t=>t.id===fresh.id),existing=out.tasks.find(t=>t.id===fresh.id);
  if(!existing){
   if(original)continue; // do not resurrect a removed original record
   const keyword=fresh.id==='handover-linkedin'?'linkedin':fresh.id==='handover-github'?'github':null;
   const duplicate=out.tasks.find(t=>keyword?t.title.toLowerCase().includes(keyword):t.title===fresh.title);
   if(duplicate){conflicts.push({id:duplicate.id,title:duplicate.title,field:'优先级/下一步',proposed:fresh.nextAction});continue;}
   out.tasks.push(structuredClone(fresh));continue;
  }
  const beforeUpdate=structuredClone(existing);
  for(const [field,value] of Object.entries(fresh)){
   if(field==='id'||value===original?.[field])continue;
   if(existing.status==='完成'&&['week','status','today','focus','nextAction'].includes(field))continue;
   if(existing.archived){conflicts.push({id:existing.id,title:existing.title,field,proposed:value});continue;}
   if(existing[field]===original?.[field]||existing[field]===undefined){
    if(field==='week'&&existing.week){out.weekSnapshots=out.weekSnapshots||{};out.weekSnapshots[existing.week]=out.weekSnapshots[existing.week]||[];if(!out.weekSnapshots[existing.week].some(t=>t.id===existing.id))out.weekSnapshots[existing.week].push(beforeUpdate);}
    existing[field]=value;
   }
   else if(existing[field]!==value)conflicts.push({id:existing.id,title:existing.title,field,proposed:value});
  }
 }
 out.baseline=SEED.baseline;out.handoverConflicts=conflicts;return out;
}
function migrateSavedState(){
 if(storageError||state.baseline===SEED.baseline)return;
 try{
  localStorage.setItem(KEY+'-before-update-'+SEED.baseline+'-'+Date.now(),JSON.stringify(state));
  const merged=mergeHandover(state);
  localStorage.setItem(KEY,JSON.stringify(merged));state=merged;
 }catch(e){storageError='交接更新未保存，原记录已保留；请导出备份后重试。'}
}
