document.addEventListener('submit',e=>{const f=e.target.closest('.quick-add');if(!f)return;e.preventDefault();let title=f.q.value.trim();if(!title)return;let priority='中';if(/[!！]$/.test(title)){priority='高';title=title.replace(/[!！]+$/,'').trim();if(!title)return}
 state.tasks.push({id:crypto.randomUUID(),title,group:f.dataset.group||'求职操作',line:f.dataset.line||'',status:'待办',priority,week,due:'',note:'',nextAction:'',focus:'',today:f.dataset.today==='1',todayAt:f.dataset.today==='1'?today():'',archived:false});
 save();const key=f.dataset.key;render();focusQuick(key)});
function startTitleEdit(el){const t=state.tasks.find(x=>x.id===el.dataset.title);if(!t||el.querySelector('input'))return;const inp=document.createElement('input');inp.className='title-input';inp.value=t.title;inp.setAttribute('aria-label','修改任务标题');el.replaceChildren(inp);inp.focus();inp.select();let finished=false;
 const finish=ok=>{if(finished)return;finished=true;const v=inp.value.trim();if(ok&&v&&v!==t.title){t.title=v;save()}render()};
 inp.addEventListener('keydown',ev=>{if(ev.key==='Enter'){ev.preventDefault();finish(true)}else if(ev.key==='Escape'){ev.preventDefault();finish(false)}});inp.addEventListener('blur',()=>finish(true))}
