document.addEventListener('keydown',e=>{if(e.target.id==='search'&&e.key==='Escape'&&e.target.value){e.preventDefault();e.target.value='';query='';render();return}if(e.key==='/'&&['jobs','contacts'].includes(view)&&!$('#editor').open){const t=(e.target.tagName||'').toLowerCase();if(!['input','textarea','select'].includes(t)){const i=$('#search');if(i){e.preventDefault();i.focus();i.select()}return}}const tag=(e.target.tagName||'').toLowerCase(),typing=['input','textarea','select'].includes(tag)||e.target.isContentEditable;
 if(e.key==='Enter'&&e.target.matches?.('[data-title]')){e.preventDefault();startTitleEdit(e.target);return}
 if(!typing&&!e.ctrlKey&&!e.metaKey&&!e.altKey&&(e.key==='n'||e.key==='N')&&!$('#editor').open){const i=document.querySelector('.quick-add input');if(i){e.preventDefault();i.focus()}}});

