function sourceEngines(s){return [...new Set((s?.source_engines||[s?.engine]).filter(e=>e==='codex'||e==='claude'))]}
function employerInfo(x){if(!x)return null;const s=x.scout||{};const n=String(x.title||'').trim().toLowerCase();let best=null,bl=0;for(const e of (employerProfiles?.employers||[]))for(const k of (e.match||[])){const kk=String(k).trim().toLowerCase();if(kk&&kk.length>bl&&n.startsWith(kk)&&!/[a-z0-9]/.test(n.charAt(kk.length))){best=e;bl=kk.length}}const cat=s.employer_category||best?.category||'';const type=s.employer_type||best?.type||'';const about=s.employer_about||best?.about||'';return (type||about)?{cat,type,about}:null}
function orgKind(cat){return ['natlab','institute','university'].includes(cat)?['lab','科研单位']:cat?['co','公司']:null}
function orgBadge(x){const i=employerInfo(x);const k=i&&orgKind(i.cat);return i&&i.type?`${k?`<span class="org-kind org-kind-${k[0]}">${k[1]}</span>`:''}<span class="org-badge org-${esc(/^[a-z]+$/.test(i.cat)?i.cat:'other')}" title="${esc(i.about||'')}">${esc(i.type)}</span>`:''}
function orgDetail(x){const i=employerInfo(x);if(!i)return '';return `<div class="org-detail">${orgBadge(x)}${i.about?`<div class="org-about"><b>关于这家单位</b>　${esc(i.about)}</div>`:''}</div>`}
function sourceBadges(s){return sourceEngines(s).map(e=>`<span class="source-badge source-${e}">${e==='codex'?'ChatGPT':'Claude'}</span>`).join('')}
function sourceScoreRows(s){const scores=s?.engine_scores||{};return sourceEngines(s).length>1?`<div class="source-comparison">${sourceEngines(s).map(e=>{const q=scores[e];return q?`<div>${sourceBadges({engine:e})} ${esc(q.total??'—')}/100 · ${esc(q.interest??'—')}/${esc(q.capability??'—')}/${esc(q.attainability??'—')}/${esc(q.role_quality??'—')}</div>`:''}).join('')}</div>`:''}
function scoreCell(x){const s=x.scout;if(!s)return '<span class="meta">—</span>';return `<strong class="score">${esc(s.total??'—')}</strong>${s.review_disposition==='withdrawn'?badge('复核撤回'):''}<div class="meta">${esc(s.interest)}/${esc(s.capability)}/${esc(s.attainability)}/${esc(s.role_quality)}${s.gap_flags?.length?' · '+s.gap_flags.map(g=>badge('缺口:'+g)).join(''):''}</div><div class="source-inline">${sourceBadges(s)}</div>`}
function scoutDetail(x){const s=x.scout||{};const row=(k,v)=>v?`<div class="kv"><span class="k">${k}</span><span class="v">${v}</span></div>`:'';const r=s.research||{};
 return `${orgDetail(x)}<div class="scout-head"><strong class="score">${esc(s.total??'—')}</strong><span class="meta">兴趣 ${esc(s.interest??'—')} · 能力 ${esc(s.capability??'—')} · 竞争机会 ${esc(s.attainability??'—')} · 岗位质量 ${esc(s.role_quality??'—')}</span></div>
 ${row('地点',esc(s.location))}${row('薪资',esc(s.salary||'未披露'))}${row('工作许可',esc(s.eligibility||'JD 未写'))}${row('发布日期',esc(s.posted_at||'未知')+(s.stale_risk?'（超过 60 天，需确认是否仍开放）':''))}${row('可补齐缺口',(s.gap_flags||[]).map(g=>badge(g)).join(''))}${row('<b>亮点</b>',esc(s.highlight))}${row('<b>注意</b>',esc(s.risk))}${row('官网',x.url?`<a href="${esc(x.url)}" target="_blank" rel="noopener">${esc(x.url)}</a>`:'')}${row('来源',sourceBadges(s)+(s.run_id?`<span class="meta">${esc(s.run_id)}</span>`:''))}${s.review_disposition==='withdrawn'?row('复核撤回',esc(s.review_reason||'')):''}${sourceScoreRows(s)}${row('<b>我的疑问</b>',esc(x.comment))}
 <div class="research"><b>深度调研</b>${r.checked_at?`<span class="meta"> · ${esc(r.checked_at)}</span>`:''}${r.checked_at?`${row('资金状况',esc(r.funding))}${row('团队 / 导师',esc(r.team))}${row('投递策略',esc(r.apply_strategy))}${row('对我疑问的回答',esc(r.answers))}${row('其他',esc(r.notes))}${row('来源',(r.sources||[]).map(u=>`<a href="${esc(u)}" target="_blank" rel="noopener">${esc(u.replace(/^https?:\/\//,'').slice(0,60))}</a>`).join('<br>'))}`:'<div class="meta">尚未调研。高分岗位可让 Claude 调研公司资金、团队与导师资质，结果会显示在这里。</div>'}</div>`}
function inboxCard(j,role){const s=j.scout||{};return `<div class="row inbox-card ${role==='副'?'is-secondary':''}"><div class="grow"><div class="task-title">${role?`<span class="role-tag ${role==='主'?'main':''}">${role}</span>`:''}${orgBadge(j)}<strong class="score">${esc(s.total??'—')}</strong> <b>${hl(j.title)}</b> — ${hl(j.detail)}${role==='副'?badge(j.kind):''} ${j.url?`<a href="${esc(j.url)}" target="_blank" rel="noopener">官网 ↗</a>`:''}</div>${(()=>{const i=employerInfo(j);return i&&i.about?`<div class="org-about">${esc(i.about)}</div>`:''})()}<div class="meta">${sourceBadges(s)}${badge(j.kind)}${j.priority?badge(j.priority+'优先'):''}${s.salary?badge(s.salary):badge('薪资未披露')}${s.eligibility?badge('许可:'+s.eligibility):''}${(s.gap_flags||[]).map(g=>badge('缺口:'+g)).join('')}${s.interview_coding?`<span title="${esc(s.interview_coding_basis||'')}">${badge('编程面试:'+({light:'轻',practical:'实操',heavy:'刷题',unknown:'未知'}[s.interview_coding]||s.interview_coding))}</span>`:''}${s.location?badge(s.location):''}</div>${s.highlight?`<div class="note"><b>亮点</b>　${esc(s.highlight)}</div>`:''}${s.risk?`<div class="note"><b>注意</b>　${esc(s.risk)}</div>`:''}<textarea class="comment" data-comment="${esc(j.id)}" rows="1" placeholder="我的疑问 / 备注（点“处理”后会连同这些问题一起调研）">${esc(j.comment||'')}</textarea></div><div class="inbox-actions">${starBtn(j,true)}<button class="small primary" data-act="process" data-id="${esc(j.id)}">处理</button><button class="small" data-act="apply" data-id="${esc(j.id)}">直接准备申请</button><button class="small" data-act="later" data-id="${esc(j.id)}">稍后</button><button class="small" data-act="ignore" data-id="${esc(j.id)}">忽略</button><button class="small" data-edit="jobs:${esc(j.id)}">详情</button></div></div>`}
function coveragePanel(){const ST={done:['已完成','cov-done'],partial:['进行中','cov-partial'],todo:['未开始','cov-todo'],deferred:['暂缓','cov-deferred'],manual:['需本人操作','cov-manual']};if(!channelCoverage){return `<details class="panel" style="margin-top:18px"><summary><b>搜索渠道覆盖</b> <span class="meta">连接共享文件夹后自动读取 data/scout/channel-coverage.json</span></summary><p class="meta">尚未读到渠道覆盖文件。</p></details>`}const rows=channelCoverage.rows||[];const n=rows.filter(r=>r.status==='done').length,pa=rows.filter(r=>r.status==='partial').length,td=rows.filter(r=>r.status==='todo').length;return `<details class="panel" style="margin-top:18px"><summary><b>搜索渠道覆盖 · 已完成 ${n} · 进行中 ${pa} · 未开始 ${td} / 共 ${rows.length}</b> <span class="meta">更新于 ${esc(channelCoverage.updated_at||'')}（${esc(channelCoverage.updated_by||'')}）</span></summary><div class="table-wrap"><table><thead><tr><th>渠道</th><th>档</th><th>状态</th><th>说明</th><th>最近一轮</th><th>负责</th></tr></thead><tbody>${rows.map(r=>{const [t,c]=ST[r.status]||[r.status,''];return `<tr><td><strong>${esc(r.channel)}</strong></td><td>${esc(r.tier)}</td><td><span class="badge ${c}">${esc(t)}</span>${r.progress?`<div class="meta">${esc(r.progress)}</div>`:''}</td><td class="meta">${esc(r.note)}</td><td class="meta">${esc(r.last_run||'—')}</td><td class="meta">${esc(r.owner||'')}</td></tr>`}).join('')}</tbody></table></div></details>`}
function withdrawnPanel(){const roles=state.jobs.filter(j=>!j.archived&&j.status==='待浏览'&&j.scout?.review_disposition==='withdrawn'&&(market==='全部'||j.market===market)&&matchQuery(j));if(!roles.length)return '';return `<details class="panel" style="margin-top:18px"><summary><b>复核撤回 · ${roles.length} 个岗位</b> <span class="meta">原推荐未达当前标准；你的状态和备注保留</span></summary>${roles.map(j=>`<div class="row"><div class="grow">${orgBadge(j)}<b>${esc(j.title)}</b> — ${esc(j.detail)} ${sourceBadges(j.scout)}<div class="meta">${esc(j.scout?.review_previous_total??'—')} → ${esc(j.scout?.total??'未评分')} / 100 · ${esc(j.scout?.review_reason||'复核撤回')}</div></div><button class="small" data-edit="jobs:${esc(j.id)}">详情</button></div>`).join('')}</details>`}
function inboxPanel(){const inbox=state.jobs.filter(j=>!j.archived&&j.status==='待浏览'&&j.scout?.review_disposition!=='withdrawn'&&(market==='全部'||j.market===market)&&matchQuery(j)).sort((p,q)=>(q.scout?.total||0)-(p.scout?.total||0));
 const groups=[];for(const j of inbox){const key=(j.title||'').trim().toLowerCase()+'|'+j.kind;let g=groups.find(x=>x.key===key);if(!g){g={key,employer:j.title,roles:[]};groups.push(g)}g.roles.push(j)}
 const groupCard=g=>{const [main,...rest]=g.roles;return `<div class="company-group">${inboxCard(main,rest.length?'主':'')}${rest.length?`<details class="secondary"><summary>同一公司还有 ${rest.length} 个岗位（副对象，先投主对象，招聘人员问起时再提）</summary>${rest.map(r=>inboxCard(r,'副')).join('')}</details>`:''}</div>`};
 const lt=groups.filter(g=>g.roles[0].kind!=='Bridge'),br=groups.filter(g=>g.roles[0].kind==='Bridge');
 const sec=(t,sub,arr,cls)=>`<div class="panel inbox-section ${cls}"><div class="inbox-sec-head"><h2>${t}</h2><span class="meta">${sub} · ${arr.reduce((n,g)=>n+g.roles.length,0)} 个岗位 / ${arr.length} 家</span></div>${arr.map(groupCard).join('')||empty('暂无。')}</div>`;
 if(query&&!inbox.length)return '';return `<div class="panel accent" style="margin-bottom:22px"><h2>待浏览 · ${inbox.length}</h2><p class="meta">引擎新扫到并过线的岗位，按公司归组、按分数排序；同一公司分数最高的为<b>主对象</b>，其余收在下方作<b>副对象</b>。<b>处理</b>进入待评估并触发调研；<b>直接准备申请</b>跳过评估；<b>稍后</b>降为低优先；<b>忽略</b>不再出现。</p>${inbox.length?'':empty('没有待浏览的岗位。'+(fs.handle?'':'连接共享文件夹后可自动导入。'))}</div>${inbox.length?`<div class="inbox-columns">${sec('长期全职','FTE · 长期岗位',lt,'is-lt')}${sec('过渡岗位','Bridge · 研究员项目 / 博士后 / 短期',br,'is-br')}</div>`:''}`}
const fs={handle:null,ready:false,lastError:'',lastImport:'',db:null,timer:null,
 statusText(){if(location.protocol==='file:')return '当前是直接双击打开的页面（file://），浏览器不允许连接文件夹。请改用桌面目录里的「启动求职工作台.cmd」打开。';if(!('showDirectoryPicker' in window))return '当前浏览器不支持本地文件夹写入（需要 Chrome 或 Edge）。';if(!this.handle)return '尚未连接共享文件夹。';if(!this.ready)return '已记住文件夹，等待授权访问。';return '已连接：'+this.handle.name+(this.lastImport?' · '+this.lastImport:'')+(this.lastError?' · '+this.lastError:'')},
 async openDb(){if(this.db)return this.db;return this.db=await new Promise((res,rej)=>{const r=indexedDB.open('job-search-dashboard-fs',1);r.onupgradeneeded=()=>r.result.createObjectStore('handles');r.onsuccess=()=>res(r.result);r.onerror=()=>rej(r.error)})},
 async load(){try{const db=await this.openDb();this.handle=await new Promise((res,rej)=>{const t=db.transaction('handles').objectStore('handles').get('root');t.onsuccess=()=>res(t.result||null);t.onerror=()=>rej(t.error)});if(this.handle){const p=await this.handle.queryPermission({mode:'readwrite'});if(p==='granted'){await this.activate()}else this.banner()}}catch(e){this.lastError='读取文件夹记录失败'}this.paint()},
 async store(){const db=await this.openDb();await new Promise((res,rej)=>{const t=db.transaction('handles','readwrite').objectStore('handles').put(this.handle,'root');t.onsuccess=res;t.onerror=()=>rej(t.error)})},
 async connect(){try{this.handle=await window.showDirectoryPicker({mode:'readwrite',id:'job-search-dashboard'});await this.store();await this.activate();render()}catch(e){if(e.name!=='AbortError'){this.lastError='连接失败：'+e.message;this.paint()}}},
 async grant(){try{const p=await this.handle.requestPermission({mode:'readwrite'});if(p==='granted'){await this.activate();render()}}catch(e){this.lastError='授权失败：'+e.message;this.paint()}},
 async activate(){this.ready=true;this.lastError='';document.getElementById('fsBanner')?.remove();await this.importInbox(false);await this.writeState(false)},
 banner(){if(document.getElementById('fsBanner'))return;const n=$('#notice');n.insertAdjacentHTML('afterend','<p id="fsBanner" class="notice"><strong>本地文件夹自动保存已暂停：</strong>浏览器需要你再次允许访问。 <button id="fsBannerGrant" class="small primary">允许访问共享文件夹</button></p>')},
 paint(){const el=$('#fsStatus');if(el)el.textContent=this.statusText()},
 async dir(parts,create){let d=this.handle;for(const p of parts)d=await d.getDirectoryHandle(p,{create});return d},
 async writeText(parts,name,text){const d=await this.dir(parts,true);const f=await d.getFileHandle(name,{create:true});const w=await f.createWritable();await w.write(text);await w.close()},
 async readText(parts,name){try{const d=await this.dir(parts,false);const f=await d.getFileHandle(name);return await (await f.getFile()).text()}catch(e){return null}},
 async writeState(manual){if(!this.ready)return;try{const payload={...state,savedAt:new Date().toISOString(),source:'dashboard-autosave'};await this.writeText(['data','state'],'dashboard-state.json',JSON.stringify(payload,null,1));this.lastError='';if(manual){this.lastImport='已写入 '+new Date().toLocaleTimeString('zh-CN',{hour:'2-digit',minute:'2-digit'});this.paint()}}catch(e){this.lastError='写入失败：'+e.message;this.paint()}},
 async importInbox(manual){if(!this.ready)return;try{let added=0,updated=0,revised=0,found=0;for(const name of ['inbox-claude.json','inbox-codex.json','inbox.json']){const txt=await this.readText(['data','scout'],name);if(!txt)continue;found++;const box=JSON.parse(txt);for(const r of (box.jobs||[])){if(!r.opportunity_id||!r.employer||!r.title)continue;const id='scout-'+String(r.opportunity_id).replace(/[^a-zA-Z0-9_-]/g,'-');const scout={review_disposition:'recommended',review_outcome:null,review_reason:'',salary_flag:r.salary_flag||null,total:r.score_total,interest:r.scores?.interest,capability:r.scores?.capability,attainability:r.scores?.attainability,role_quality:r.scores?.role_quality,salary:r.salary_text||'',eligibility:r.eligibility||'',gap_flags:r.gap_flags||[],interview_coding:r.interview_coding||'',employer_type:r.employer_type||'',employer_category:r.employer_category||'',employer_about:r.employer_about||'',interview_coding_basis:r.interview_coding_basis||'',engine:(r.engine||box.generated_by||'').toLowerCase(),posted_at:r.posted_at||'',stale_risk:!!r.stale_risk,location:r.location||'',highlight:r.highlight||'',risk:r.risk||'',run_id:r.run_id||'',opportunity_id:r.opportunity_id};const engine=scout.engine==='codex'||scout.engine==='claude'?scout.engine:'';const snapshot={total:scout.total,interest:scout.interest,capability:scout.capability,attainability:scout.attainability,role_quality:scout.role_quality,run_id:scout.run_id};scout.source_engines=engine?[engine]:[];scout.engine_scores=engine?{[engine]:snapshot}:{};const ex=state.jobs.find(j=>j.id===id);if(ex){const prior=ex.scout||{};const old=prior.engine_scores||((prior.engine==='codex'||prior.engine==='claude')?{[prior.engine]:{total:prior.total,interest:prior.interest,capability:prior.capability,attainability:prior.attainability,role_quality:prior.role_quality,run_id:prior.run_id}}:{});if(r.deadline&&!ex.deadline){ex.deadline=r.deadline;ex.deadlineBasis=r.deadline_basis||'官网写明'}ex.scout={...prior,...scout,source_engines:[...new Set([...sourceEngines(prior),...scout.source_engines])],engine_scores:{...old,...scout.engine_scores}};updated++;continue}state.jobs.push({id,title:r.employer,detail:r.title,market:r.market||'美国',kind:r.category==='bridge'?'Bridge':'长期 FTE',status:'待浏览',priority:(r.score_total||0)>=80?'高':'中',url:r.url||'',due:'',deadline:r.deadline||'',deadlineBasis:r.deadline?(r.deadline_basis||'官网写明'):'',note:'',archived:false,today:false,scout,importedAt:today()});added++}
   for(const r of (box.revisions||[])){if(!r.opportunity_id||!['below','triaged_out'].includes(r.disposition))continue;const id='scout-'+String(r.opportunity_id).replace(/[^a-zA-Z0-9_-]/g,'-');const ex=state.jobs.find(j=>j.id===id);if(!ex)continue;const prior=ex.scout||{};const score=r.scores||{};const old=prior.engine_scores||{};const eng=String(r.engine||box.generated_by||'codex').toLowerCase()==='claude'?'claude':'codex';const codex={total:r.score_total??null,interest:score.interest??null,capability:score.capability??null,attainability:score.attainability??null,role_quality:score.role_quality??null,run_id:r.run_id||box.run_id||''};ex.scout={...prior,review_disposition:'withdrawn',review_outcome:r.disposition,review_reason:r.review_reason||'',review_previous_total:r.previous_score??prior.total??null,total:codex.total,interest:codex.interest,capability:codex.capability,attainability:codex.attainability,role_quality:codex.role_quality,eligibility:r.eligibility||prior.eligibility||'',gap_flags:r.gap_flags||[],salary:r.salary_text||prior.salary||'',salary_flag:r.salary_flag||null,risk:r.risk||prior.risk||'',run_id:codex.run_id,source_engines:[...new Set([...sourceEngines(prior),eng])],engine_scores:{...old,[eng]:codex}};revised++}}
  let decided=0;const dtxt=await this.readText(['data','scout'],'chat-decisions.json');if(dtxt){try{const dj=JSON.parse(dtxt);state.appliedChatDecisions=state.appliedChatDecisions||[];for(const d of (dj.items||[])){if(!d.decision_id||state.appliedChatDecisions.includes(d.decision_id))continue;const j=state.jobs.find(x=>x.id===d.job_id||(d.opportunity_id&&x.scout?.opportunity_id===d.opportunity_id));if(!j)continue;if(d.status&&j.status!==d.status){j.status=d.status;j.decidedAt=(d.requested_at||today()).slice(0,10);if(d.note)j.note=(j.note?j.note+'\n':'')+d.note;decided++}else if(d.note&&!d.status){j.note=(j.note?j.note+'\n':'')+d.note}if(d.deadline!==undefined){j.deadline=d.deadline;j.deadlineBasis=d.deadline_basis||j.deadlineBasis||'';decided++}if(d.starred!==undefined){j.starred=!!d.starred;j.starredAt=j.starred?(d.requested_at||today()).slice(0,10):'';decided++}if(d.due!==undefined){j.due=d.due;decided++}if(d.applied_at!==undefined){j.appliedAt=d.applied_at;decided++}state.appliedChatDecisions.push(d.decision_id)}if(decided){found++;updated+=decided}}catch(e){}}
  const ctxt=await this.readText(['data','scout'],'channel-coverage.json');let coverageChanged=false;if(ctxt){try{const cj=JSON.parse(ctxt);if(JSON.stringify(cj)!==JSON.stringify(channelCoverage)){channelCoverage=cj;coverageChanged=true}}catch(e){}}const etxt=await this.readText(['data','scout'],'employer-profiles.json');if(etxt){try{const ej=JSON.parse(etxt);if(JSON.stringify(ej)!==JSON.stringify(employerProfiles)){employerProfiles=ej;coverageChanged=true}}catch(e){}}
  let researched=0;const rtxt=await this.readText(['data','scout'],'research.json');if(rtxt){const rj=JSON.parse(rtxt);for(const j of state.jobs){const oid=j.scout?.opportunity_id;const r=oid&&rj.items?.[oid];if(r&&JSON.stringify(j.scout.research||null)!==JSON.stringify(r)){j.scout.research=r;researched++}}}
  if(!found&&!rtxt){if(manual){this.lastImport='未找到 inbox-claude.json / inbox-codex.json';this.paint()}return}this.lastImport=`inbox 导入：新增 ${added}，更新 ${updated}，复核撤回 ${revised}${decided?`，聊天决定 ${decided}`:''}`+(researched?`，调研更新 ${researched}`:'');if(researched)updated+=researched;if(added||updated||revised){localStorage.setItem(KEY,JSON.stringify(state));if(manual)await this.writeState(false);render()}else if(coverageChanged){render()}this.paint()}catch(e){this.lastError='inbox 读取失败：'+e.message;this.paint()}}
};
function scheduleFileSave(){if(!fs.ready)return;clearTimeout(fs.timer);fs.timer=setTimeout(()=>fs.writeState(false),800)}
// —— 搜索（2026-10-09 Claude）：按公司、岗位、地点、状态、备注等字段匹配；多个词用空格隔开，需全部命中 ——
let lastJobHits=0;
function searchTerms(){return String(query||'').toLowerCase().split(/\s+/).filter(Boolean)}
function searchText(x){const s=x.scout||{};return [x.title,x.detail,x.market,x.kind,x.status,x.priority&&x.priority+'优先',x.comment,x.note,x.url,s.location,s.highlight,s.risk,s.employer_type,s.salary,s.opportunity_id].filter(Boolean).join(' \u0001 ').toLowerCase()}
function matchQuery(x){const ts=searchTerms();if(!ts.length)return true;const t=searchText(x);return ts.every(q=>t.includes(q))}
function hl(v){const h=esc(v),ts=searchTerms();if(!ts.length)return h;const re=new RegExp('('+ts.map(q=>esc(q).replace(/[.*+?^${}()|[\]\\]/g,'\\$&')).join('|')+')','gi');return h.split(/(&[a-z0-9#]+;)/i).map(part=>/^&[a-z0-9#]+;$/i.test(part)?part:part.replace(re,'<mark>$1</mark>')).join('')}
function searchSummary(){if(view!=='jobs'||!query){lastJobHits=0;return ''}
 const pool=state.jobs.filter(j=>(market==='全部'||j.market===market)&&matchQuery(j)),live=pool.filter(j=>!j.archived),arch=pool.length-live.length;lastJobHits=live.length;
 const B=[['待浏览',j=>j.status==='待浏览'],['正在推进',j=>['待评估','准备申请'].includes(j.status)],['已投递',j=>APPLIED.includes(j.status)],['稍后',j=>j.status==='稍后'],['不再跟进',j=>['暂不继续','已结束'].includes(j.status)]];
 const parts=B.map(([n,f])=>[n,live.filter(f).length]).filter(x=>x[1]).map(([n,c])=>`${n} ${c}`);const starred=live.filter(j=>j.starred).length;
 return `<div class="panel search-summary"><b>搜索「${esc(query)}」：找到 ${live.length} 个岗位</b>${live.length?`<span class="meta">　${parts.join(' · ')}${starred?` · 其中收藏 ${starred}`:''}</span>`:''}<div class="meta">${live.length?'匹配结果在下面各栏里，折叠的栏目已自动展开，匹配文字已标黄。':'没有匹配的岗位。可以换个词，或只输入公司名的一部分（例如 acme、engineer、实习）。'}${arch?` 另有 ${arch} 个已归档的岗位匹配，勾选右上方「查看归档」可看。`:''}${market!=='全部'?` 当前只看「${esc(market)}」市场。`:''}</div></div>`}

// —— 任务关联岗位（2026-10-09 Claude）：任务详情里直接看到对应岗位、官网与投递摘要 ——
// 已有投递任务的预设对应（任务 ID → 岗位 ID）；你在任务详情里手动选的「关联岗位」优先于这里。
const TASK_JOB_LINKS={};
const CN_ALIAS=[['字节','bytedance'],['亚马逊','amazon'],['英伟达','nvidia'],['微软','microsoft'],['谷歌','google']];
const KEY_STOP=['research','institute','national','university','the','labs','laboratory','laboratories','center','centre','company','group','team','applied','open','data'];
const DETAIL_HINT=[['博士后','postdoc'],['驻留','residency'],['实习','intern'],['机器人','robotics'],['安全','safety']];
function jobById(id){return state.jobs.find(j=>j.id===id)}
function companyBase(j){return String(j.title||'').toLowerCase().replace(/\s*[（(][^)）]*[)）]\s*/g,' ').trim()}
function companyKeys(j){const t=String(j.title||'').toLowerCase().trim(),base=companyBase(j),keys=new Set([t,base]);for(const m of t.matchAll(/[（(]([^)）]+)[)）]/g)){const a=m[1].trim();if(a.length>=3&&!/[·,，]/.test(a))keys.add(a)}const w=base.split(/\s+/)[0];if(w&&w.length>=3&&!KEY_STOP.includes(w))keys.add(w);keys.delete('');return [...keys]}
function hasWord(text,k){let i=text.indexOf(k);while(i>=0){const a=text.charAt(i-1),b=text.charAt(i+k.length);if(!/[a-z0-9]/.test(a)&&!/[a-z0-9]/.test(b))return true;i=text.indexOf(k,i+1)}return false}
function taskText(t,withNext){let s=(t.title||'')+(withNext?' '+(t.nextAction||''):'');s=s.toLowerCase();for(const [cn,en] of CN_ALIAS)if(s.includes(cn))s+=' '+en;for(const [cn,en] of DETAIL_HINT)if(s.includes(cn))s+=' '+en;return s}
const APPLY_WORDS=/投|申请|面试|提案|陈述|推荐|材料|联系|apply|application|interview|offer|referral/i;
function autoJobs(t){if(!APPLY_WORDS.test(t.title||''))return [];for(const withNext of [false,true]){const text=taskText(t,withNext);const hits=state.jobs.filter(j=>!j.archived&&!['暂不继续','已结束'].includes(j.status)&&companyKeys(j).some(k=>hasWord(text,k)));if(!hits.length)continue;
  const byCo={};for(const j of hits)(byCo[companyBase(j)]=byCo[companyBase(j)]||[]).push(j);let out=[];
  for(const list of Object.values(byCo)){const score=j=>String(j.detail||'').toLowerCase().split(/[^a-z0-9]+/).filter(w=>w.length>=4&&!KEY_STOP.includes(w)&&hasWord(text,w)).length;const best=Math.max(...list.map(score));let pick=list.filter(j=>score(j)===best);if(pick.length>2){const pref=pick.filter(j=>j.starred||['准备申请','待评估'].includes(j.status)||APPLIED.includes(j.status));if(pref.length)pick=pref}pick.sort((a,b)=>(b.starred?1:0)-(a.starred?1:0)||(b.scout?.total||0)-(a.scout?.total||0));out.push(...pick.slice(0,2))}
  return out.slice(0,4)}return []}
function linkedJobs(t){if(!t)return {jobs:[],mode:'none'};if(t.jobIds==='none')return {jobs:[],mode:'off'};if(t.jobIds){return {jobs:t.jobIds.split(',').map(id=>jobById(id.trim())).filter(Boolean),mode:'manual'}}const pre=TASK_JOB_LINKS[t.id];if(pre){const js=pre.map(jobById).filter(Boolean);if(js.length)return {jobs:js,mode:'preset'}}return {jobs:autoJobs(t),mode:'auto'}}
function jobShort(j,all){const ab=(String(j.title||'').match(/[（(]([^)）·,，]{2,12})[)）]/)||[])[1];const co=(ab||String(j.title||'').replace(/\s*[（(][^)）]*[)）]\s*/g,'')).trim()||j.title;const twin=all.filter(x=>companyBase(x)===companyBase(j)).length>1;return co+(twin?' · '+String(j.detail||'').replace(/^(Researcher|Research Scientist|Applied Scientist)\s*[—–-]\s*/,'').slice(0,22):'')}
function taskJobChips(t){const {jobs}=linkedJobs(t);if(!jobs.length)return '';return `<div class="job-chips">${jobs.map(j=>`<button type="button" class="job-chip" data-edit="jobs:${esc(j.id)}" title="${esc(j.title+' — '+(j.detail||'')+'（点击打开岗位详情）')}">↗ ${esc(jobShort(j,jobs))} <span>${esc(j.status)}</span></button>`).join('')}</div>`}
function taskJobsBlock(t){const {jobs,mode}=linkedJobs(t);const how={manual:'你手动选的',preset:'按任务内容预设',auto:'按任务标题里的公司名自动匹配',off:'已设为不关联',none:''}[mode]||'';
 return `<div class="wide task-jobs"><div class="tj-head"><b>关联岗位</b>${how&&jobs.length?`<span class="meta">${how}；不对的话在下方「关联岗位」里改</span>`:''}</div>${jobs.map(j=>`<div class="tj-card">${orgBadge(j)}<strong>${esc(j.title)}</strong><div class="meta">${esc(j.detail||'')}</div><div class="tj-actions">${badge(j.status)}${j.deadline&&!APPLIED.includes(j.status)?dlBadge(j):''}${j.url?`<a href="${esc(j.url)}" target="_blank" rel="noopener">岗位官网 ↗</a>`:''}${appSummary(j)?`<a href="${esc(appSummary(j))}" target="_blank" rel="noopener"><b>投递摘要 ↗</b></a>`:''}<button type="button" class="small" data-edit="jobs:${esc(j.id)}">打开岗位记录 ›</button></div></div>`).join('')||`<div class="meta">${mode==='off'?'这条任务设为不关联岗位。':'没有匹配到岗位。在下方「关联岗位」里选一个即可。'}</div>`}</div>`}
function jobTasksBlock(j){const ts=state.tasks.filter(t=>!t.archived&&linkedJobs(t).jobs.some(x=>x.id===j.id));if(!ts.length)return '';return `<div class="wide task-jobs"><div class="tj-head"><b>相关任务 · ${ts.length}</b></div>${ts.map(t=>`<div class="tj-card tj-task"><span class="${t.status==='完成'?'done':''}">${esc(t.title)}</span> ${badge(t.status)}<button type="button" class="small" data-edit="tasks:${esc(t.id)}">打开任务 ›</button></div>`).join('')}</div>`}
function jobPicker(item){const cur=item.jobIds||'';const auto=linkedJobs({...item,jobIds:''});const autoLabel=auto.jobs.length?'自动：'+auto.jobs.map(j=>jobShort(j,auto.jobs)).join('、'):'自动匹配（目前没匹配到）';const live=state.jobs.filter(j=>!j.archived&&!['暂不继续','已结束'].includes(j.status));
 const opt=j=>`<option value="${esc(j.id)}" ${cur===j.id?'selected':''}>${esc(j.title)} — ${esc(String(j.detail||'').slice(0,60))}（${esc(j.status)}）</option>`;const by=(a,b)=>String(a.title).localeCompare(String(b.title));
 const groups=[['★ 重点关注',live.filter(j=>j.starred)],['正在推进',live.filter(j=>!j.starred&&['待评估','准备申请'].includes(j.status))],['已投递',live.filter(j=>!j.starred&&APPLIED.includes(j.status))],['待浏览',live.filter(j=>!j.starred&&j.status==='待浏览')],['稍后',live.filter(j=>!j.starred&&j.status==='稍后')]];
 const multi=cur&&cur!=='none'&&cur.includes(',')?`<option value="${esc(cur)}" selected>当前：${esc(cur.split(',').map(id=>jobById(id)?.title||id).join('、'))}</option>`:'';
 return `<select name="jobIds"><option value="" ${cur?'':'selected'}>${esc(autoLabel)}</option><option value="none" ${cur==='none'?'selected':''}>不关联岗位</option>${multi}${groups.filter(g=>g[1].length).map(([n,a])=>`<optgroup label="${n}">${a.sort(by).map(opt).join('')}</optgroup>`).join('')}</select>`}
migrateSavedState();
if(rollOver())save();
render();
document.addEventListener('visibilitychange',()=>{if(!document.hidden)rollOverNow()});setInterval(rollOverNow,10*60*1000);
fs.load().then(()=>render());

function jumpTo(k){const el=k==='star'?document.getElementById('starPanel'):k==='soon'?document.getElementById('calSoon'):k==='follow'?document.getElementById('followPanel'):k==='applied'?document.querySelector('[data-stage="applied"]'):k==='inbox'?document.querySelector('#content .panel'):null;if(!el)return;el.scrollIntoView({behavior:'smooth',block:'start'});el.classList.remove('flash');void el.offsetWidth;el.classList.add('flash')}

// —— 日历与截止（2026-10-02 Claude）——
function dayDiff(d){return Math.round((new Date(d+'T00:00:00')-new Date(today()+'T00:00:00'))/864e5)}
function leftText(d){const n=dayDiff(d);return n===0?'今天':n>0?`还剩 ${n} 天`:`已过 ${-n} 天`}
function dlBadge(x){const n=dayDiff(x.deadline);return `<span class="badge dl ${n<0?'late':n<=14?'dl-soon':''}">截止 ${esc(x.deadline)} · ${leftText(x.deadline)}${x.deadlineBasis&&x.deadlineBasis!=='官网写明'?'（'+esc(x.deadlineBasis)+'）':''}</span>`}
function calItems(){const out=[];for(const j of state.jobs){if(j.archived||CAL_CLOSED.includes(j.status))continue;if(j.deadline&&!APPLIED.includes(j.status))out.push({type:'deadline',date:j.deadline,x:j,kind:'jobs'});if(j.due)out.push({type:'follow',date:j.due,x:j,kind:'jobs'})}for(const c of state.contacts||[]){if(c.archived||c.status==='已完成'||!c.due)continue;out.push({type:'follow',date:c.due,x:c,kind:'contacts'})}return out.sort((a,b)=>a.date.localeCompare(b.date)||(a.type==='deadline'?-1:1))}
function soonDeadlines(){return calItems().filter(i=>i.type==='deadline'&&dayDiff(i.date)<=14)}
function calRow(i){const x=i.x,n=dayDiff(i.date);return `<div class="row cal-row ${i.type}"><div class="cal-date ${n<0?'past':n<=14?'soon':''}"><b>${esc(i.date.slice(5).replace('-','/'))}</b><span>${leftText(i.date)}</span></div><div class="grow"><span class="cal-type ${i.type}">${i.type==='deadline'?'投递截止':'我的跟进'}</span>${i.kind==='jobs'?orgBadge(x):''}<strong>${esc(x.title)}</strong>${x.detail?`<div class="meta">${esc(x.detail)}</div>`:''}<div>${badge(x.status)}${i.type==='deadline'&&x.deadlineBasis&&x.deadlineBasis!=='官网写明'?badge(x.deadlineBasis):''}${x.url?` <a class="meta" href="${esc(x.url)}" target="_blank" rel="noopener">官网 ↗</a>`:''}</div></div>${i.kind==='jobs'?starBtn(x):''}<button class="small" data-edit="${i.kind}:${esc(x.id)}">查看</button></div>`}
function shiftMonth(m,k){let [y,mo]=m.split('-').map(Number);mo+=k;while(mo<1){mo+=12;y--}while(mo>12){mo-=12;y++}return y+'-'+String(mo).padStart(2,'0')}
function monthGrid(items){const [y,m]=calMonth.split('-').map(Number);const first=new Date(y,m-1,1),days=new Date(y,m,0).getDate(),lead=(first.getDay()+6)%7;let cells='';for(let i=0;i<lead;i++)cells+='<div class="cal-cell blank"></div>';for(let d=1;d<=days;d++){const ds=calMonth+'-'+String(d).padStart(2,'0');const its=items.filter(i=>i.date===ds);cells+=`<div class="cal-cell ${ds===today()?'is-today':''}"><span class="cal-num">${d}</span>${its.map(i=>`<button class="cal-chip ${i.type}" data-edit="${i.kind}:${esc(i.x.id)}" title="${esc((i.type==='deadline'?'投递截止 · ':'我的跟进 · ')+i.x.title+' '+(i.x.detail||''))}">${esc(i.x.title)}</button>`).join('')}</div>`}return `<div class="panel"><div class="cal-head"><h2>${y} 年 ${m} 月</h2><div><button class="small" data-cal-month="-1">‹ 上月</button> <button class="small" data-cal-month="0" onclick="calMonth=today().slice(0,7)">本月</button> <button class="small" data-cal-month="1">下月 ›</button></div></div><div class="cal-legend"><span class="cal-type deadline">投递截止</span><span class="cal-type follow">我的跟进</span></div><div class="cal-grid">${['一','二','三','四','五','六','日'].map(w=>`<div class="cal-wd">${w}</div>`).join('')}${cells}</div></div>`}
function calendarView(){const items=calItems();const past=items.filter(i=>dayDiff(i.date)<0),soon=items.filter(i=>{const n=dayDiff(i.date);return n>=0&&n<=14}),mid=items.filter(i=>{const n=dayDiff(i.date);return n>14&&n<=60}),late=items.filter(i=>dayDiff(i.date)>60);
 const nodl=state.jobs.filter(j=>!j.archived&&['待评估','准备申请','稍后'].includes(j.status)&&!j.deadline);const browsing=state.jobs.filter(j=>!j.archived&&j.status==='待浏览'&&!j.deadline).length;
 const sec=(id,t,sub,arr,cls)=>`<div class="panel cal-sec ${cls}" ${id?`id="${id}"`:''} style="margin-top:18px"><h2>${t} · ${arr.length}</h2><p class="meta">${sub}</p>${arr.map(calRow).join('')||empty('没有。')}</div>`;
 return `<div class="panel accent"><h2>日历与截止</h2><p class="meta">两类日期分开显示：<b>投递截止</b>是单位规定的最后投递日（投出后自动不再提醒）；<b>我的跟进</b>是你自己定的回看日期。截止日期在岗位「查看 / 编辑」里填写，并注明依据（官网写明 / 按往期推测 / 滚动）。</p></div>`
 +sec('','已过期','截止已过但还没投的岗位，或已到期的跟进：处理后改日期或改状态',past,'past')
 +sec('calSoon','两周内（含今天）','提前两周提醒：这些需要优先安排',soon,'soon')
 +sec('','15–60 天','',mid,'')+(late.length?sec('','60 天以后','',late,''):'')
 +monthGrid(items)
 +`<div class="panel" style="margin-top:18px"><h2>没有固定截止日期 / 还没查 · ${nodl.length}</h2><p class="meta">正在推进或暂缓、但还没填截止日期的岗位。「滚动 / 未写明」表示官网没写，通常招满即止，宜早投。另有 ${browsing} 条待浏览岗位未列出。</p>${nodl.map(j=>`<div class="row"><div class="grow">${orgBadge(j)}<strong>${esc(j.title)}</strong><div class="meta">${esc(j.detail||'')}</div><div>${badge(j.status)}${badge(j.deadlineBasis||'未查')}</div></div><button class="small" data-edit="jobs:${esc(j.id)}">填写</button></div>`).join('')||empty('都已填写。')}</div>`}

// —— 收藏 / 重点关注（2026-10-02 Claude）——
function starBtn(j,wide){return `<button class="small star-btn ${j.starred?'on':''}" data-star="${esc(j.id)}" title="${j.starred?'取消收藏':'收藏到重点关注'}" aria-pressed="${j.starred?'true':'false'}">${j.starred?'★':'☆'}${wide?(j.starred?' 已收藏':' 收藏'):''}</button>`}
function starredJobs(){const CLOSED=['暂不继续','已结束'];const key=j=>j.deadline&&!APPLIED.includes(j.status)?j.deadline:(j.due||'9999');return state.jobs.filter(j=>j.starred&&!j.archived).sort((a,b)=>(CLOSED.includes(a.status)?1:0)-(CLOSED.includes(b.status)?1:0)||key(a).localeCompare(key(b))||(b.scout?.total||0)-(a.scout?.total||0))}
// 2026-10-09 Claude：重点关注分「待处理 / 已处理」。已处理 = 已投递及以后，或暂不继续 / 已结束；默认收起。
function starHandled(j){return APPLIED.includes(j.status)||['暂不继续','已结束'].includes(j.status)}
function starPanel(compact){let arr=starredJobs();if(!compact&&query)arr=arr.filter(matchQuery);if(!compact&&query&&!arr.length)return '';
 const todo=arr.filter(j=>!starHandled(j)),done=arr.filter(starHandled).sort((a,b)=>(APPLIED.includes(a.status)?0:1)-(APPLIED.includes(b.status)?0:1)||String(b.appliedAt||b.decidedAt||'').localeCompare(String(a.appliedAt||a.decidedAt||'')));
 const nApplied=done.filter(j=>APPLIED.includes(j.status)).length,nClosed=done.length-nApplied;
 const doneSub=[nApplied?`已投递 ${nApplied}`:'',nClosed?`不再跟进 ${nClosed}`:''].filter(Boolean).join(' · ');
 const row=j=>{const sc=j.scout?.total,applied=APPLIED.includes(j.status);return `<div class="row star-row ${['暂不继续','已结束'].includes(j.status)?'is-closed':''}">${starBtn(j)}<div class="grow">${orgBadge(j)}<strong>${hl(j.title)}</strong>${sc!=null?` <span class="meta">· ${esc(sc)} 分</span>`:''}<div class="meta">${hl(j.detail||'')}${j.url?` · <a href="${esc(j.url)}" target="_blank" rel="noopener">官网 ↗</a>`:''}${appSummary(j)?` · <a href="${esc(appSummary(j))}" target="_blank" rel="noopener"><b>投递摘要 ↗</b></a>`:''}</div><div>${badge(j.status)}${applied&&j.appliedAt?badge('投递于 '+j.appliedAt):''}${j.deadline&&!applied?dlBadge(j):(compact||applied?'':badge('截止：'+(j.deadlineBasis||'未查')))}${j.due?due(j.due).replace('class="badge','class="badge fu'):''}</div>${!compact&&!applied&&j.note?`<div class="note meta">${esc(j.note.split('\n').slice(-1)[0]).slice(0,140)}</div>`:''}</div><button class="small" data-edit="jobs:${esc(j.id)}">查看</button></div>`};
 const head=`<h2>★ 重点关注 · 待处理 ${todo.length}${done.length?` <span class="star-head-done">· 已处理 ${done.length}</span>`:''}</h2>`;
 if(compact){const shown=todo.slice(0,6);return `<div class="panel star-panel" id="starPanel" style="margin-top:20px">${head}<p class="meta">收藏的岗位里还没投、也没放弃的；按最近的截止或跟进日期排序。</p>${shown.map(row).join('')||empty(arr.length?'收藏的岗位都已处理。':'还没有收藏。到「机会与投递」里，在觉得特别好的岗位旁点 ☆。')}${todo.length>6||done.length?`<p class="meta">${todo.length>6?`还有 ${todo.length-6} 个待处理`:''}${todo.length>6&&done.length?'；':''}${done.length?`已处理 ${done.length} 个（${doneSub}）已收起`:''} <button class="small linkish" data-view="jobs" data-jump="star">全部查看 ›</button></p>`:''}</div>`}
 const doneOpen=query?true:!!stageOpen.stardone;
 return `<div class="panel star-panel" id="starPanel" style="margin-bottom:22px">${head}<p class="meta">你收藏的岗位分两栏：<b>待处理</b>是还没投、也没放弃的，按最近的截止或跟进日期排序；投出去或决定不跟进后，自动移到下方<b>已处理</b>（默认收起）。点 ☆ 收藏，再点一次取消。</p>${todo.map(row).join('')||empty(arr.length?(query?'待处理里没有匹配的岗位。':'收藏的岗位都已处理。'):'还没有收藏。在觉得特别好的岗位旁点 ☆。')}${done.length?`<details class="star-done" data-stage="stardone" ${doneOpen?'open':''}><summary><b>已处理 · ${done.length}</b> <span class="meta">${doneSub}</span></summary>${done.map(row).join('')}</details>`:''}</div>`}
